"""Delivery preview and explicit activation of the named, approved outreach batch."""

# ruff: noqa: E501 - embedded dashboard assets.

DELIVERY_SCRIPT = r"""<script>
document.addEventListener('DOMContentLoaded',()=>{
const view=document.getElementById('outreachView');
view.insertAdjacentHTML('beforeend','<div class="view-heading"><h2>Automatic outreach queue</h2><p id="automationMode">Checking automation…</p></div><div class="toolbar"><button type="button" class="btn" id="prepareDelivery">Prepare approved leads</button><button type="button" class="btn" id="refreshDelivery">Refresh delivery</button><span id="deliveryStatus" class="sub" role="status"></span></div><div class="table-wrap"><table><thead><tr><th>Recipient</th><th>Next action</th><th>Delivery status</th><th>Result</th><th>Controls</th></tr></thead><tbody id="deliveryRows"></tbody></table></div>');
document.body.insertAdjacentHTML('beforeend','<dialog id="deliveryDialog"><form id="deliveryForm"><div class="modal-head"><div><h2 id="deliveryRecipient">Enable delivery</h2><p class="sub">Uses the LinkedIn account signed in on the local worker computer.</p></div><button type="button" class="close" id="closeDelivery" aria-label="Close delivery preview">x</button></div><div class="form-grid"><div class="field full"><strong id="deliveryKind"></strong><div class="profile-value" id="deliveryDraft"></div></div><div class="field full" id="followUpPreview"><strong>Follow-up after connection acceptance</strong><div class="profile-value" id="deliveryFollowUp"></div><label><input type="checkbox" id="allowFollowUp" style="width:auto"> Also enable this exact follow-up after first-degree connection acceptance is confirmed.</label></div><div class="field full"><label><input type="checkbox" id="confirmDelivery" required style="width:auto"> <span id="deliveryConsentText">I authorize sending the displayed draft to this named recipient.</span></label><p class="sub">Daily campaign limits apply. Unconfirmed deliveries stop for manual inspection and are never blindly resent.</p></div></div><div class="field full" id="resolveFields" hidden style="padding:0 22px"><label for="resolveNote">What did you check on LinkedIn?</label><textarea id="resolveNote" minlength="10" maxlength="1000"></textarea></div><div class="modal-actions"><span id="authorizeResult" class="sub" role="status"></span><button type="submit" class="btn primary" id="authorizeDelivery">Enable delivery</button></div></form></dialog>');
const el=id=>document.getElementById(id);let current=null,serial=0,resolving=false;
function cell(row,value){const td=document.createElement('td');td.textContent=value??'';row.append(td);return td}
function control(text,action){const b=document.createElement('button');b.type='button';b.className='icon-btn';b.textContent=text;b.onclick=action;return b}
async function post(path,payload={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await r.json();if(!r.ok)throw Error(typeof body.detail==='string'?body.detail:'Could not update delivery');return body}
function preview(job,resolve=false){current=job;resolving=resolve;el('deliveryForm').reset();el('resolveFields').hidden=!resolve;el('resolveNote').required=resolve;el('deliveryConsentText').textContent=resolve?'I checked LinkedIn and confirm this invitation/message was NOT sent.':'I authorize sending the displayed draft to this named recipient.';el('authorizeDelivery').textContent=resolve?'Confirm not sent':'Enable delivery';el('authorizeResult').textContent='';el('deliveryRecipient').textContent=(resolve?'Resolve unconfirmed delivery: ':'Enable delivery to ')+job.payload.name;el('deliveryKind').textContent=job.action==='connection'?'Connection request note':'Follow-up message';el('deliveryDraft').textContent=job.payload.draft;el('deliveryFollowUp').textContent=job.payload.follow_up;el('followUpPreview').hidden=resolve||job.action!=='connection';el('deliveryDialog').showModal()}
async function refreshDelivery(){const id=++serial;try{const r=await fetch('/api/outreach/jobs');if(!r.ok)throw Error('Could not load delivery queue');const data=await r.json();if(id!==serial)return;el('automationMode').textContent=data.automatic_qualification?'Profile fetching and qualification run automatically. Eligible complete profiles are auto-approved. '+(data.automatic_queue?'Approved leads are queued automatically. ':'')+'Enable delivery after reviewing the recipient and exact drafts below.':'Research and review mode. Prepare approved leads to preview delivery.';const rows=el('deliveryRows');rows.replaceChildren();for(const job of data.jobs){const row=document.createElement('tr');cell(row,job.payload.name);cell(row,{connection:'Connection request',check:'Check acceptance',message:'Follow-up message'}[job.action]);cell(row,job.status==='queued'&&!job.authorized?'Awaiting delivery authorization':job.status.replaceAll('_',' '));cell(row,job.result?.proof||'');const actions=cell(row,'');if(job.status==='queued'){if(!job.authorized&&job.action!=='check')actions.append(control('Review / enable delivery',()=>preview(job)));if(job.action==='check')actions.append(control('Check acceptance now',async()=>{try{await post('/api/outreach/jobs/'+job.id+'/check-now');await refreshDelivery()}catch(error){el('deliveryStatus').textContent=error.message}}));actions.append(control('Cancel unstarted action',async()=>{try{await post('/api/outreach/jobs/'+job.id+'/cancel');await Promise.all([refreshDelivery(),load(),loadSummary()])}catch(error){el('deliveryStatus').textContent=error.message}}))}if(job.status==='uncertain'){if(job.action==='check')actions.append(control('Retry acceptance check',async()=>{try{await post('/api/outreach/jobs/'+job.id+'/check-now');await refreshDelivery()}catch(error){el('deliveryStatus').textContent=error.message}}));else{actions.append(control('Verify / record actual outcome',()=>window.openManualActivity(job.lead_id)));actions.append(control('Confirm not sent',()=>preview(job,true)))}}rows.append(row)}el('deliveryStatus').textContent=data.jobs.length?data.jobs.length+' delivery records':'No delivery jobs yet. Only approved, qualifying leads can be prepared.';}catch(error){el('deliveryStatus').textContent=error.message}}
el('prepareDelivery').onclick=async e=>{e.currentTarget.disabled=true;try{const data=await post('/api/outreach/prepare');notice(data.prepared+' approved leads prepared. No message has been sent.');await Promise.all([refreshDelivery(),load(),loadSummary()])}catch(error){el('deliveryStatus').textContent=error.message}finally{el('prepareDelivery').disabled=false}};
el('refreshDelivery').onclick=()=>Promise.all([refreshDelivery(),load(),loadSummary()]);el('closeDelivery').onclick=()=>el('deliveryDialog').close();
el('deliveryForm').onsubmit=async e=>{e.preventDefault();const button=el('authorizeDelivery');button.disabled=true;try{if(resolving)await post('/api/outreach/jobs/'+current.id+'/resolve-not-sent',{confirmed:el('confirmDelivery').checked,note:el('resolveNote').value});else await post('/api/outreach/jobs/'+current.id+'/authorize',{draft_hash:current.draft_hash,confirmed:el('confirmDelivery').checked,include_follow_up:el('allowFollowUp').checked});el('deliveryDialog').close();notice(resolving?'Outcome recorded as not sent. Prepare again only after verifying LinkedIn.':'Delivery enabled for the named recipient. Keep the worker computer online.');await Promise.all([refreshDelivery(),load(),loadSummary()])}catch(error){el('authorizeResult').textContent=error.message}finally{button.disabled=false}};
refreshDelivery();setInterval(refreshDelivery,15000);
});
</script>"""

